crlf.source:
cicada 2
track left acid { level = -8dB }
track right acid { level = -10dB }
pattern pulse { 1 . 5 . }
arrange {
  place bed left pulse { at = @1.1.1 length = 4bars }
  place pickup right pulse { at = @2.2.1 length = 1/4 }
  marker later { at = @3.1.1 }
  marker opening { at = @1.1.1 }
  marker middle { at = @2.1.1 }
  place print sampler print-clip { at = @5.1.1 length = 2080ticks }
}
track sampler audio {}


asset print-audio "sampler/audio/print.wav" { sha256 = "abababababababababababababababababababababababababababababababab" format = wav frames = 48000 rate = 48000Hz channels = 2 }
clip print-clip print-audio { start = 0frames end = 48000frames fade_in = 240frames fade_out = 240frames }

